// Wide game oracle: runs the REAL Minecraft: Java Edition classes on many
// random seeds and writes what Chunkscope must reproduce, for a large-scale
// check (`crates/mc-core/tests/wide.rs`). The output is not committed: it is
// regenerated by the weekly workflow (and before releases) and compared there.
//
// Run it through parity/game-oracle/wide.sh, which compiles it with
// GameOracle.java, whose helpers it reuses.
//
// Per seed, in every dimension:
//   biomes.txt       dim seed qx qy qz biome          (random quart positions, near and far)
//   heights.txt      dim seed x z worldSurface oceanFloor   (getBaseHeight, *_WG)
//   structures.txt   dim seed set cx cz attempts...   (every attempt of every random-spread
//                    set around (0, 0) and around a random far block; GameOracle's format,
//                    or "(no attempt)" for a region's candidate chunk the set rejects)
//   ships.txt        seed cx cz yes|no                (end cities that generate)
// and for the Overworld:
//   spawn.txt        seed spawnX spawnZ originChunkX originChunkZ
//   strongholds.txt  seed x,z ...                     (every `strongholdEvery`-th seed)
// and for every seed:
//   gateways.txt     seed i0 i1 ... i19               (the order the End gateways open in)

import java.io.PrintWriter;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.SplittableRandom;

import net.minecraft.SharedConstants;
import net.minecraft.core.Holder;
import net.minecraft.core.HolderLookup;
import net.minecraft.core.registries.Registries;
import net.minecraft.data.registries.VanillaRegistries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.server.Bootstrap;
import net.minecraft.world.level.ChunkPos;
import net.minecraft.world.level.LevelHeightAccessor;
import net.minecraft.world.level.biome.Biome;
import net.minecraft.world.level.biome.BiomeSource;
import net.minecraft.world.level.biome.Climate;
import net.minecraft.world.level.biome.MultiNoiseBiomeSource;
import net.minecraft.world.level.biome.MultiNoiseBiomeSourceParameterList;
import net.minecraft.world.level.biome.MultiNoiseBiomeSourceParameterLists;
import net.minecraft.world.level.biome.TheEndBiomeSource;
import net.minecraft.world.level.chunk.ChunkGeneratorStructureState;
import net.minecraft.world.level.levelgen.Heightmap;
import net.minecraft.world.level.levelgen.NoiseBasedChunkGenerator;
import net.minecraft.world.level.levelgen.NoiseGeneratorSettings;
import net.minecraft.world.level.levelgen.RandomState;
import net.minecraft.world.level.levelgen.densityfunction.SamplerContext;
import net.minecraft.world.level.levelgen.structure.placement.RandomSpreadStructurePlacement;

public class WideOracle {
    /** Blocks around each center whose regions are scanned for structure attempts. */
    static final int AREA = 1024;
    /** At most this many regions each way from a center (nether fossils have 2-chunk regions). */
    static final int MAX_REGIONS = 8;
    /** Chunks around each center scanned for sets placed in every chunk (mineshafts, buried treasure). */
    static final int CHUNK_AREA = 6;

    record Dim(String id, NoiseGeneratorSettings settings, Holder<NoiseGeneratorSettings> holder, BiomeSource biomes,
            NoiseBasedChunkGenerator generator, LevelHeightAccessor height,
            MultiNoiseBiomeSourceParameterList.Preset preset, int minQy, int maxQy, List<String> sets) {}

    public static void main(String[] args) throws Exception {
        Path out = Path.of(args[0]);
        int count = Integer.parseInt(args[1]);
        long salt = Long.parseLong(args[2]);
        int strongholdEvery = Integer.parseInt(args[3]);
        Files.createDirectories(out);
        GameOracle.out = out;

        SharedConstants.tryDetectVersion();
        Bootstrap.bootStrap();
        HolderLookup.Provider lookup = VanillaRegistries.createWorldLookup();
        GameOracle.bindBiomeTags(lookup);
        GameOracle.bindBlockTags();

        List<net.minecraft.core.Registry<?>> registries = new ArrayList<>();
        for (var key : List.of(Registries.TEMPLATE_POOL, Registries.PROCESSOR_LIST)) registries.add(GameOracle.copyRegistry(lookup, key));
        net.minecraft.core.registries.BuiltInRegistries.REGISTRY.forEach(registries::add);
        var registryAccess = new net.minecraft.core.RegistryAccess.ImmutableRegistryAccess(registries);
        var templates = GameOracle.templateManager(lookup);
        Map<String, java.util.Set<String>> structureBiomes = new java.util.HashMap<>();
        for (var ref : lookup.lookupOrThrow(Registries.STRUCTURE).listElements().toList()) {
            String tag = ((net.minecraft.core.HolderSet.Named<Biome>) ref.value().biomes()).key().location().toString();
            structureBiomes.put(ref.key().identifier().toString(), new java.util.HashSet<>(GameOracle.biomeTag(tag)));
        }
        var sets = GameOracle.structureSets(lookup);
        var noises = lookup.lookupOrThrow(Registries.NOISE);
        var parameterLists = lookup.lookupOrThrow(Registries.MULTI_NOISE_BIOME_SOURCE_PARAMETER_LIST);

        List<Dim> dims = new ArrayList<>();
        {
            var h = lookup.lookupOrThrow(Registries.NOISE_SETTINGS).getOrThrow(NoiseGeneratorSettings.OVERWORLD);
            var b = MultiNoiseBiomeSource.createFromPreset(parameterLists.getOrThrow(MultiNoiseBiomeSourceParameterLists.OVERWORLD));
            var s = h.value().noiseSettings();
            List<String> names = new ArrayList<>();
            for (var set : sets) {
                String n = set.key().identifier().toString();
                if (!List.of("minecraft:strongholds", "minecraft:nether_complexes", "minecraft:nether_fossils",
                        "minecraft:end_cities").contains(n)) names.add(n);
            }
            dims.add(new Dim("overworld", h.value(), h, b, new NoiseBasedChunkGenerator(b, h),
                    LevelHeightAccessor.create(s.minY(), s.height()), MultiNoiseBiomeSourceParameterList.Preset.OVERWORLD,
                    -16, 80, names));
        }
        {
            var h = lookup.lookupOrThrow(Registries.NOISE_SETTINGS).getOrThrow(NoiseGeneratorSettings.NETHER);
            var b = MultiNoiseBiomeSource.createFromPreset(parameterLists.getOrThrow(MultiNoiseBiomeSourceParameterLists.NETHER));
            // dimension_type/the_nether.json: y 0 to 255.
            dims.add(new Dim("nether", h.value(), h, b, new NoiseBasedChunkGenerator(b, h), LevelHeightAccessor.create(0, 256),
                    MultiNoiseBiomeSourceParameterList.Preset.NETHER, 0, 64,
                    List.of("minecraft:nether_complexes", "minecraft:nether_fossils", "minecraft:ruined_portals")));
        }
        {
            var h = lookup.lookupOrThrow(Registries.NOISE_SETTINGS).getOrThrow(NoiseGeneratorSettings.END);
            var b = TheEndBiomeSource.create(lookup.lookupOrThrow(Registries.BIOME));
            // dimension_type/the_end.json: y 0 to 255.
            dims.add(new Dim("end", h.value(), h, b, new NoiseBasedChunkGenerator(b, h), LevelHeightAccessor.create(0, 256),
                    null, 0, 64, List.of("minecraft:end_cities")));
        }

        SplittableRandom rnd = new SplittableRandom(salt);
        var ctor = ChunkGeneratorStructureState.class.getDeclaredConstructor(RandomState.class, BiomeSource.class, long.class,
                ChunkPos.class, long.class, List.class);
        ctor.setAccessible(true);
        long started = System.nanoTime();
        try (PrintWriter biomes = GameOracle.writer("biomes.txt"); PrintWriter heights = GameOracle.writer("heights.txt");
                PrintWriter structures = GameOracle.writer("structures.txt"); PrintWriter ships = GameOracle.writer("ships.txt");
                PrintWriter spawn = GameOracle.writer("spawn.txt"); PrintWriter strongholds = GameOracle.writer("strongholds.txt");
                PrintWriter gateways = GameOracle.writer("gateways.txt")) {
            for (int i = 0; i < count; i++) {
                long seed = rnd.nextLong();
                for (Dim d : dims) {
                    RandomState rs = RandomState.create(noises, seed, d.settings());
                    // Biomes. A fresh R-tree per seed and dimension: its search starts from the last
                    // result, and Chunkscope's starts from nothing for each world.
                    var sampler = rs.createClimateSampler(SamplerContext.builder().build());
                    var tree = d.preset() == null ? null
                            : new Climate.ParameterList<>(MultiNoiseBiomeSourceParameterList.knownPresets().get(d.preset()).values());
                    var resolver = d.biomes().createResolver(sampler);
                    for (int k = 0; k < 64; k++) {
                        int range = k % 2 == 0 ? 1_000 : 7_500_000;
                        int qx = rnd.nextInt(-range, range), qz = rnd.nextInt(-range, range);
                        int qy = rnd.nextInt(d.minQy(), d.maxQy());
                        String biome = tree != null ? tree.findValue(sampler.sample(qx, qy, qz)).identifier().toString()
                                : resolver.getNoiseBiome(qx, qy, qz).unwrapKey().orElseThrow().identifier().toString();
                        biomes.println(d.id() + " " + seed + " " + qx + " " + qy + " " + qz + " " + biome);
                    }
                    // Terrain heights.
                    for (int k = 0; k < 6; k++) {
                        int range = k % 2 == 0 ? 2_000 : 1_000_000;
                        int x = rnd.nextInt(-range, range), z = rnd.nextInt(-range, range);
                        int ws = d.generator().getBaseHeight(x, z, Heightmap.Types.WORLD_SURFACE_WG, d.height(), rs);
                        int of = d.generator().getBaseHeight(x, z, Heightmap.Types.OCEAN_FLOOR_WG, d.height(), rs);
                        heights.println(d.id() + " " + seed + " " + x + " " + z + " " + ws + " " + of);
                    }
                    // Every structure attempt around (0, 0) and around a far block.
                    var state = ctor.newInstance(rs, d.biomes(), seed, new ChunkPos(0, 0), seed, List.copyOf(sets));
                    int[][] centers = {{0, 0}, {rnd.nextInt(-1_000_000, 1_000_000), rnd.nextInt(-1_000_000, 1_000_000)}};
                    for (var setRef : sets) {
                        String setName = setRef.key().identifier().toString();
                        if (!d.sets().contains(setName)) continue;
                        var set = setRef.value();
                        var placement = (RandomSpreadStructurePlacement) set.placement();
                        for (int[] c : centers) {
                            List<ChunkPos> chunks = new ArrayList<>();
                            int ccx = c[0] >> 4, ccz = c[1] >> 4;
                            if (placement.spacing() == 1) {
                                for (int cz = ccz - CHUNK_AREA; cz <= ccz + CHUNK_AREA; cz++)
                                    for (int cx = ccx - CHUNK_AREA; cx <= ccx + CHUNK_AREA; cx++) chunks.add(new ChunkPos(cx, cz));
                            } else {
                                int s = placement.spacing(), r = Math.min(Math.ceilDiv(AREA, s * 16), MAX_REGIONS);
                                int rx0 = Math.floorDiv(ccx, s), rz0 = Math.floorDiv(ccz, s);
                                for (int rz = rz0 - r; rz <= rz0 + r; rz++)
                                    for (int rx = rx0 - r; rx <= rx0 + r; rx++) chunks.add(placement.getPotentialStructureChunk(seed, rx * s, rz * s));
                            }
                            for (ChunkPos pos : chunks) {
                                StringBuilder sb = new StringBuilder(d.id() + " " + seed + " " + setName + " " + pos.x() + " " + pos.z());
                                if (!placement.isStructureChunk(state, pos.x(), pos.z())) {
                                    // A region's candidate the set rejects (frequency, exclusion zone): Chunkscope
                                    // must not try it either. Not listed for sets placed in every chunk.
                                    if (placement.spacing() > 1) structures.println(sb + " (no attempt)");
                                    continue;
                                }
                                GameOracle.selectStructure(sb, set, seed, pos, registryAccess, d.generator(), d.biomes(), rs, templates,
                                        d.height(), structureBiomes);
                                structures.println(sb);
                                if (setName.equals("minecraft:end_cities") && !sb.toString().endsWith(":no")
                                        && !sb.toString().endsWith(":nopieces")) {
                                    ships.println(seed + " " + pos.x() + " " + pos.z() + " "
                                            + (hasShip(set, seed, pos, registryAccess, d, rs, templates, structureBiomes) ? "yes" : "no"));
                                }
                            }
                        }
                    }
                    if (d.id().equals("overworld")) {
                        var samplers = rs.samplersWithContext(SamplerContext.builder().enableCaches().build());
                        var p = net.minecraft.world.level.levelgen.NoiseSpawnFinder.findSpawnPosition(d.settings().spawnTarget(), samplers);
                        var origin = d.generator().getOrigin(rs);
                        spawn.println(seed + " " + p.getX() + " " + p.getZ() + " " + origin.x() + " " + origin.z());
                        if (strongholdEvery > 0 && i % strongholdEvery == 0) strongholds.println(GameOracle.strongholdLine(lookup, d.biomes(), rs, seed));
                    }
                }
                // The End gateways' order: what EnderDragonFight.init does with the world seed.
                List<Integer> order = new java.util.ArrayList<>();
                for (int g = 0; g < 20; g++) order.add(g);
                net.minecraft.util.Util.shuffle(order, net.minecraft.util.RandomSource.createThreadLocalInstance(seed));
                gateways.println(seed + " " + order.stream().map(String::valueOf).collect(java.util.stream.Collectors.joining(" ")));
                if ((i + 1) % 10 == 0 || i + 1 == count) {
                    System.out.printf("%d/%d seeds (%.0f s)%n", i + 1, count, (System.nanoTime() - started) / 1e9);
                }
            }
        }
        try (PrintWriter w = GameOracle.writer("SEEDS")) {
            w.println("count " + count + " salt " + salt + " strongholdEvery " + strongholdEvery);
        }
    }

    /** Whether the end city that generates at `pos` has a ship (Structure.generate, then its pieces). */
    static boolean hasShip(net.minecraft.world.level.levelgen.structure.StructureSet set, long seed, ChunkPos pos,
            net.minecraft.core.RegistryAccess registryAccess, Dim d, RandomState rs,
            net.minecraft.world.level.levelgen.structure.templatesystem.StructureTemplateManager templates,
            Map<String, java.util.Set<String>> structureBiomes) {
        var entry = set.structures().get(0);
        var biomes = structureBiomes.get(entry.structure().unwrapKey().orElseThrow().identifier().toString());
        java.util.function.Predicate<Holder<Biome>> valid = h -> biomes.contains(h.unwrapKey().orElseThrow().identifier().toString());
        var start = entry.structure().value().generate(entry.structure(), net.minecraft.world.level.Level.END, registryAccess,
                d.generator(), d.biomes(), rs.createClimateSampler(SamplerContext.builder().enableCaches().build()), rs, templates,
                seed, pos, 0, d.height(), valid);
        for (var piece : start.getPieces()) {
            if ("ship".equals(GameOracle.get(piece, "templateName"))) return true;
        }
        return false;
    }
}
